11	  new Promise((resolve, reject) => {
12	    const child = spawn("node_modules/.bin/tsx", ["src/cli.ts"]);
13	    let stdout = "";
14	    let stderr = "";
15	    child.stdout.on("data", (chunk) => (stdout += chunk));
16	    child.stderr.on("data", (chunk) => (stderr += chunk));
17	    child.on("error", reject);
18	    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
19	    child.stdin.end(input);
20	  });
